            "pxp_is_the_body_0_at_rest": "PXP bedendir, <0>dinlenme hâlinde</0> — <1>ağırlık</1> ve <2>söz</2>.",
            "pixa_is_one_living_being_and_pxa": "Pixa tek bir canlı varlıktır; PXA ve PXP onun <0>bedenidir</0> — <1>Atlas</1>, iki fazda tek madde. PXP <2> katı fazdır</2>: varlığa <3> ağırlık</3> (yönetişim) ve ücretsiz bant genişliği vermek için 1:1 donmuş PXA. Aynı zamanda <4>zihni</4> yönelten safradır — witness'lar stake edilmiş PXP ile seçilir; yani zihin, bedenin kendi hakkında ürettiği bir şeydir. İstediğin zaman, hiçbir tarafın değiştiremeyeceği on üç haftalık serbest bırakmayla likit PXA'ya geri erit.",
            "pxp_is_pxa_0_frozen_solid_0": "PXP, <0>katıya donmuş</0> PXA'dır — bedene ağırlık ve söz vermek için bire bir stake edilmiştir. <1>Erit</1>, on üç haftalık serbest bırakmayla likit PXA'ya geri döner. Aynı madde, iki faz; birlikte <2>Atlas</2>'tırlar.",
            "staking_is_not_idle_it_buys_four": "Stake etmek boş durmak değildir. Dört şey satın alır — ve bunlardan biri sessizce zihni yöneltir.",
