            "bears_the_weight_pxa_pxp_together_liquid": "Ağırlığı taşır. PXA + PXP birlikte — likit ve stake edilmiş, iki fazda tek madde. Yaratıcı emekten yapılmıştır.",
            "what_you_actually_hold_pxs_the_body_observed": "Gerçekte elinde tuttuğun. PXS — zihin aracılığıyla gözlemlenen beden. Ayrı bir varlık değil; uyanmış beden.",
