            "twenty_one_witnesses_elected_by_staked_pxp_each": "Stake edilmiş PXP ile seçilen yirmi bir witness'ın her biri bir okuma yayımlar: bir Big Mac'in, bir kahvenin yerel fiyatı — satın alma gücü, bir para birimi değil. Bildirenler teminat tabanı tarafından seçildiği için referans, tabanın kendi hakkında ürettiği bir modeldir.",
            "two_stage_median": "İki aşamalı medyan",
            "doubly_median_84_h": "çifte medyan · 84 sa",
            "a_median_across_the_twenty_one_witnesses_rejects": "Yirmi bir witness arasındaki medyan, bozuk bir bildireni eler; 84 saatlik pencere üzerindeki medyan — üç buçuk gün, saatlik örneklenmiş — anlık bir sıçramayı eler. Bozması pahalı, manipüle etmesi yavaş: güvenle değil, yapısı gereği sağlam. Merkez bankası yok, IMF sepeti yok, BIS beslemesi yok.",
            "settlement": "Sonuçlanma",
            "reading_haircut": "okuma × kesinti",
            "when_you_settle_the_atlas_is_delivered": "Sonuçlandırdığında Atlas, yürütme anında PXA olarak teslim edilir — Oracle'ın adlandırdığı okuma, geçerli kesintiyle çarpılmış hâliyle. Hiçbir taraf müdahale etmez; hiçbir insan imzalamaz.",
            "tired_body": "Yorgun beden",
            "below_3": "3× altı",
            "below_the_floor_the_haircut_falls_linearly_toward": "Tabanın altında kesinti doğrusal olarak sıfıra iner. Sonuçlanma, okumadan kesinlikle daha azını teslim eder — ruh, bedenin yorgun olduğunu dürüstçe işaret eder. Dürüstlük, istikrar sağlama değil.",
            "viable_corridor": "Yaşanabilir koridor",
