            "effective_in_strong_strong_day": "— <strong>%n</strong> {{{_plurals.day}}} içinde geçerli olur",
            "adding_a_password_provides_extra_security_especi": "Şifre eklemek, özellikle kısa seed ifadeleri için ek güvenlik sağlar.",
            "you_are_about_to_request_a_change": "<0>@{{username}}</0> için kurtarma hesabı değişikliği talep etmek üzeresin.",
            "nominate_a_trusted_account_a_co_founder": "Owner anahtarın kaybolur veya ele geçirilirse erişimi geri kazanmana yardım etmesi için güvendiğin bir hesap belirle — bir kurucu ortak, kontrol ettiğin bir kardeş cüzdan veya başka bir kanaldan ulaşabildiğin bir kişi. Kurtarma akışı owner anahtarı geçmişini kullanır; bu yüzden kurtarma hesabı tek başına hesabını asla ele geçiremez: yalnızca kurtarmana yardım edebilir. Değişiklikler 30 günlük bekleme süresinden sonra geçerli olur.",
            "strong_30_day_waiting_period_strong_changing": "<strong>30 günlük bekleme süresi.</strong> Kurtarma hesabını değiştirmek anlık değildir. Yeni bir talep <strong>yayından 30 gün sonra</strong> geçerli olur; o zamana kadar mevcut kurtarma hesabı geçerli kalır. Bekleme süresinde yeniden yayınlamak bekleyen talebi değiştirir. Mevcut değere geri ayarlamak bekleyen değişikliği iptal eder.",
            "pick_someone_you_trust_personally_a_co": "Kişisel olarak güvendiğin birini seç — bir kurucu ortak, kontrol ettiğin bir kardeş hesap veya sahibine başka bir kanaldan ulaşabildiğin bir cüzdan.",
            "generate_a_fresh_seed_phrase_to_derive": "Hesabın için yeni anahtarlar türetmek üzere taze bir seed ifadesi oluştur. Seed ifaden tüm hesap anahtarlarının ana anahtarıdır — güvende tut ve asla paylaşma. Aşağıda onayladığında anahtar güncelleme işlemini imzalamak için owner anahtarı kullanılacak.",
            "this_will_strong_cancel_any_pending_recovery": "Bu, mevcut kurtarma hesabınla aynı değeri yeniden yayınlayarak <strong>bekleyen kurtarma hesabı değişikliğini iptal eder</strong>. 30 günlük bekleyen talep değiştirilir; mevcut kurtarma hesabı bu süre boyunca geçerli kalır.",
            "once_broadcast_the_chain_will_create_a": "Yayınlandığında zincir, <strong>30 gün</strong> içinde geçerli olacak bekleyen bir talep oluşturur. Mevcut kurtarma hesabın (<0>@{{currentRecovery}}</0>) o zamana kadar geçerli kalır. Senden <strong>owner anahtarı</strong> istenecek.",
            "posting_description_1": "Bu anahtar; gönderi paylaşma, yorum yapma ve oy verme gibi sosyal ağ işlemleri için kullanılmalıdır. Sınırlı izinlere sahiptir ve parasal işlemler için kullanılamaz.",
            "posting_description_2": "Bu anahtarı Pixagram.com gibi Pixa tabanlı sosyal ağlara giriş yapmak için kullan. Anahtarı güvenli bir yerde sakla.",
            "active_description_1": "Bu anahtar, token transferi ve takası gibi daha hassas parasal işlemler için ek izinlere sahiptir.",
            "active_description_2": "Cüzdanla ilgili bir işlem yaparken Active anahtarınla kimlik doğrulaman istenebilir. Active Key'ini yalnızca güvendiğin uygulamalara gir; bu anahtara erişen herkes tokenlarını alabilir.",
            "owner_description_1": "Diğer anahtarları değiştirmek için Owner anahtarı gereklidir. Bu anahtar, hesabını kurtarmak veya diğer anahtarlarını değiştirmek için ek izinlere sahiptir. En önemli anahtardır ve çevrimdışı olarak güvenle saklanmalıdır.",
            "memo_description_1": "Memo anahtarı biraz farklıdır. Memo Key'in yapabildiği tek şey, blokzincir üzerinden gönderilen özel mesajları şifrelemek ve şifresini çözmektir.",
