            "to_create_and_to_curate_is_worth": " Üretmek ve küratörlük etmek, sessizce elde tutmaktan daha değerlidir; ortaya çıkanlar Pixa'nın yaşayan özüdür ve o, önce onlar için kurulmuştur.",
            "and_most_beautiful_of_all_are_the": " — ve hepsinden güzeli, onları yapan ellerdir. Eserde yaratıcıyı onurlandır.",
