            "for_conquest_is_never_accomplished_no_milestone": " çünkü fetih asla tamamlanmaz. Hiçbir dönüm noktası zirve değildir; iş asla bitmez.",
            "lift_the_smallest_accounts_as_you_climb": " Yükselirken en küçük hesapları da yukarı taşı, çünkü bugünün küçük balığı yarının ustasıdır.",
            "but_treat_it_sometimes_as_an_impostor": " ama ona kimi zaman bir sahtekâr gibi davran — ve daima adil ol. Kalabalığın sevdiği şey her zaman en iyisi değildir; kendi yargıcın olarak kal.",
            "to_dislike_is_your_right_and_to": " Beğenmemek senin hakkındır ve yargılamak sansür değildir; seni kımıldatmayan her esere olumsuz oy ver ya da yanından geç.",
            "a_community_is_known_by_how_it": " Bir topluluk, kırılgan olanı nasıl koruduğuyla bilinir; gücünü yaratmaya çevir, asla bir başkasına karşı değil.",
            "let_every_tool_serve_the_creator_and": " Her araç yaratıcıya hizmet etsin ve asla onun yerini almasın.",
            "in_your_work_and_in_your_dealings": " — eserinde de, ilişkilerinde de; çünkü dürüstlük, bütün gücün üzerinde yükseldiği kayadır.",
            "contribute_to_it_not_for_today_or": " Ona bugün ya da dün için değil, tüm zamanlar için katkıda bulun.",
            "it_funds_development_and_the_protocol_the": " — geliştirmeyi ve protokolü finanse eder. Pixa'nın tanıtımı halkına aittir, asla hazinesine değil.",
