            "these_principles_are_the_foundation_of_pixa": "Bu ilkeler, Pixa'nın ve onun üzerine kurduğumuz topluluğun temelidir — dürüst, adil, kalıcı ve birlik içinde. Protokol yalnızca yasaklaması gerekeni yasaklar; o çizginin ötesindeki her iyi şey, seçtiğimiz karakterdir. İşte o karakter budur: üretirken taşıdığımız ruh, birbirimize davranış biçimimiz ve kendimizi tabi tuttuğumuz ölçü. Kimseyi zorla bağlamazlar, yine de hepimizi bağlarlar.",
