            "ownership_and_moral_rights": "Mülkiyet ve Manevi Haklar",
            "the_author_is_and_shall_remain_the_sole": "Eser Sahibi, temel eserler ve NFT'lerle bağlantılı her türlü ilişkili içerik üzerindeki tüm fikri mülkiyet haklarının tek ve münhasır sahibidir ve öyle kalacaktır. Eser Sahibi; eserin yaratıcısı olarak tanınma hakkı ile onurunu veya itibarını zedeleyecek her türlü bozma, sakatlama ya da başka bir değişikliğe itiraz etme hakkı dâhil tüm manevi haklarını saklı tutar. Bu manevi haklar devredilemez ve süreklidir; tüm Sahipler ve üçüncü taraflarca bu haklara saygı gösterilecektir. İşbu Sözleşme, bu haklardan feragat veya bu hakların sınırlandırılması olarak yorumlanamaz.",
